patch:
diff --git a/repro/emfile-fix.js b/repro/emfile-fix.js
new file mode 100644
index 0000000..4e36487
--- /dev/null
+++ b/repro/emfile-fix.js
@@ -0,0 +1,130 @@
+#!/usr/bin/env node
+/**
+ * Reproduction for: "running `--fix` throws EMFILE: too many open files"
+ * (eslint ./ --fix on a big repo with ~9000 auto-fixable files).
+ *
+ * Run from the repo root:
+ *
+ *     node repro/emfile-fix.js
+ *
+ * What it does:
+ *   1. Creates a throwaway project in a private temp dir with FILES files that
+ *      each contain one auto-fixable problem (missing semicolon).
+ *   2. Runs the real CLI from this checkout, `node bin/eslint.js ./ --fix`,
+ *      with the process's open-file limit lowered to NOFILE.
+ *   3. Asserts what the report says should happen: ESLint does not die with
+ *      EMFILE and every file with an auto-fixable issue gets fixed.
+ *
+ * Exit code: 0 when fixing works, non-zero while the bug is present.
+ *
+ * Why the limit is lowered: the reporter hit the limit on Windows with ~9000
+ * files (the stack shows Promise.all index 8189). Here the limit is lowered
+ * with `ulimit -n` so a few thousand files are enough. This is a simulation of
+ * the environment, not a Windows run.
+ *
+ * Knobs (environment variables):
+ *   FILES   number of fixable files to generate   (default 3000)
+ *   NOFILE  soft open-file limit for the CLI run  (default 1024)
+ *   KEEP=1  keep the temp project dir for inspection
+ */
+"use strict";
+
+const fs = require("node:fs");
+const os = require("node:os");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const FILES = Number(process.env.FILES || 3000);
+const NOFILE = Number(process.env.NOFILE || 1024);
+const DIRS = 20;
+
+const repoRoot = path.resolve(__dirname, "..");
+const eslintBin = path.join(repoRoot, "bin", "eslint.js");
+
+const projectDir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-emfile-"));
+
+function cleanup() {
+	if (!process.env.KEEP) {
+		fs.rmSync(projectDir, { recursive: true, force: true });
+	}
+}
+
+try {
+	// --- fixture -----------------------------------------------------------
+	fs.writeFileSync(
+		path.join(projectDir, "eslint.config.js"),
+		'module.exports = [{ rules: { semi: ["error", "always"] } }];\n',
+	);
+	for (let d = 0; d < DIRS; d++) {
+		fs.mkdirSync(path.join(projectDir, `dir${d}`));
+	}
+
+	const BROKEN = "const value = 1\n"; // missing semicolon, auto-fixable
+	const FIXED = "const value = 1;\n";
+	const files = [];
+
+	for (let i = 0; i < FILES; i++) {
+		const file = path.join(projectDir, `dir${i % DIRS}`, `file${i}.js`);
+
+		fs.writeFileSync(file, BROKEN);
+		files.push(file);
+	}
+
+	// --- run the reported command -----------------------------------------
+	// `eslint ./ --fix`, with the soft fd limit lowered for just this process.
+	const result = spawnSync(
+		"sh",
+		[
+			"-c",
+			'ulimit -n "$0" && exec "$@"',
+			String(NOFILE),
+			process.execPath,
+			eslintBin,
+			"./",
+			"--fix",
+		],
+		{ cwd: projectDir, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 },
+	);
+
+	const output = `${result.stdout || ""}${result.stderr || ""}`;
+	const unfixed = files.filter(f => fs.readFileSync(f, "utf8") !== FIXED);
+	const hitEmfile = /EMFILE/.test(output);
+	const inOutputFixes = /ESLint\.outputFixes/.test(output);
+
+	console.log(
+		`files=${FILES} nofile=${NOFILE} exit=${result.status} signal=${result.signal || "-"}`,
+	);
+	console.log(`files still unfixed after --fix: ${unfixed.length}/${FILES}`);
+	if (output.trim()) {
+		console.log("--- eslint output (first 15 lines) ---");
+		console.log(output.trim().split("\n").slice(0, 15).join("\n"));
+		console.log("--------------------------------------");
+	}
+
+	let failed = false;
+
+	if (hitEmfile) {
+		failed = true;
+		console.error(
+			`FAIL: --fix died with EMFILE${inOutputFixes ? " in ESLint.outputFixes" : " (not in outputFixes)"}`,
+		);
+	}
+	if (unfixed.length > 0) {
+		failed = true;
+		console.error(
+			`FAIL: ${unfixed.length} of ${FILES} files with auto-fixable problems were not fixed`,
+		);
+	}
+	if (result.status !== 0 && !failed) {
+		failed = true;
+		console.error(`FAIL: eslint exited with status ${result.status}`);
+	}
+
+	if (failed) {
+		process.exitCode = 1;
+	} else {
+		console.log("PASS: all files fixed, no EMFILE");
+	}
+} finally {
+	cleanup();
+}
